run('mi_drawarc', "# maxseg is kept as given: an interior circle of two 180-degree arcs (r = 10 mm) meshes as a\n# 72-gon with maxseg 5 and as a square with maxseg 90. mi_setarcsegmentprop caps maxseg at\n# 10, so setting the square's arcs to 90 that way gives a 36-gon.\nobs = []\nfor k, (maxseg, sides, viaprop) in enumerate(((5, 72, False), (90, 4, False), (90, 36, True))):\n    blank(1)\n    circle(40, 5)\n    arcprop(0, 40, 5, 'A0')\n    arcprop(0, -40, 5, 'A0')\n    mi_drawarc(10, 0, -10, 0, 180, maxseg)\n    mi_drawarc(-10, 0, 10, 0, 180, maxseg)\n    if viaprop:\n        arcprop(0, 10, maxseg, '<None>')\n        arcprop(0, -10, maxseg, '<None>')\n    label(0, 0, 'Air')\n    label(20, 20, 'Air')\n    solve('arc' + str(k))\n    mo_selectblock(0, 0)\n    mm2 = mo_blockintegral(5) / 1e-6\n    mo_close()\n    mi_close()\n    polygon = sides / 2 * math.sin(2 * math.pi / sides) * 100\n    check(abs(mm2 / polygon - 1) < 1e-4, f'case {k}, maxseg {maxseg}: area {mm2:.4f} mm^2, {sides}-gon {polygon:.4f}')\n    how = ' then mi_setarcsegmentprop(90)' if viaprop else ''\n    obs.append(f'maxseg {maxseg}{how} -> {mm2:.4f} mm^2 = {sides}-gon')\n# Direction: a 90-degree arc from (10,0) to (0,10), closed by two lines through the origin.\n# Counter-clockwise (centre at the origin) encloses a quarter disc of 78.4 mm^2;\n# clockwise (centre at (10,10)) would enclose 100 - 78.4 = 21.6 mm^2.\nblank(1)\nmi_drawarc(10, 0, 0, 10, 90, 5)\nmi_drawline(0, 10, 0, 0)\nmi_drawline(0, 0, 10, 0)\narcprop(5, 5, 5, 'A0')\nlabel(1, 1, 'Air')\nsolve('arcdir')\nmo_selectblock(1, 1)\nquarter = mo_blockintegral(5) / 1e-6\nmo_close()\nsector = 9 * 100 * math.sin(5 * math.pi / 180)\ncheck(abs(quarter / sector - 1) < 1e-3, f'area {quarter:.3f} mm^2, quarter disc {sector:.3f} mm^2')\nwrong = fails(mi_drawarc, 0, 0, 1, 1, 90)\ncheck(wrong is not None and 'missing 1 required positional argument' in wrong, 'five arguments: ' + str(wrong))\nreturn '; '.join(obs) + f'; 90-degree arc (10,0) -> (0,10): area {quarter:.2f} mm^2 = quarter disc, so counter-clockwise; five arguments: {wrong}'")
run('mi_drawline', 'blank()\nmi_drawline(0, 0, 10, 0)\nmi_drawline(5, -5, 5, 5)\nx, y = mi_selectnode(5.3, 0.2)\nmi_clearselected()\np1 = mi_selectsegment(2, 0)\np2 = mi_selectsegment(5, -3)\nmi_close()\nblank()\ncircle(10, 5)\nmi_drawline(0, 0, 20, 0.5)\nax, ay = mi_selectnode(10, 0.25)\nmi_close()\nblank()\np = [(0, 0), (10, 0), (10, 10)]\nfor k in range(len(p)):\n    mi_drawline(*p[k], *p[(k + 1) % len(p)])\nclosing = mi_selectsegment(3, 5)\nhelpers = [hasattr(femm, \'mi_drawpolygon\'), hasattr(femm, \'mi_drawpolyline\')]\nengine = fails(callfemm, \'mi_drawpolygon(0)\')\nwrong = fails(mi_drawline, 0, 0, 1)\ncheck(abs(x - 5) < 1e-9 and abs(y) < 1e-9, \'no node at the crossing: \' + show(x, y))\ncheck(p1[:2] == [0, 0] and abs(p1[2] - 5) < 1e-9 and abs(p1[3]) < 1e-9, \'first line \' + show(p1))\ncheck(p2[:2] == [5, -5] and abs(p2[2] - 5) < 1e-9 and abs(p2[3]) < 1e-9, \'second line \' + show(p2))\ncheck(abs(math.hypot(ax, ay) - 10) < 1e-6 and abs(ay - 0.025 * ax) < 1e-9, \'no node where the line crosses the circle: \' + show(ax, ay))\ncheck(closing == [10, 10, 0, 0], \'closing side \' + show(closing))\ncheck(helpers == [False, False] and engine is not None and "isn\'t defined" in engine, show(helpers, engine))\ncheck(wrong is not None and \'missing 1 required positional argument\' in wrong, \'three arguments: \' + str(wrong))\nreturn f\'crossing lines got a node at {x}, {y} and were split: {p1} and {p2}; a line through a circle got a node at ({ax:.6g}, {ay:.6g}) on it; the loop drew the closing side {closing}; no polygon helper in pyFEMM ({helpers}) or FEMM ({engine}); three arguments: {wrong}\'')
run('mi_drawrectangle', "blank()\nmi_drawrectangle(0, 0, 4, 2)\nbottom = mi_selectsegment(2, 0)\nright = mi_selectsegment(4, 1)\ntop = mi_selectsegment(2, 2)\nleft = mi_selectsegment(0, 1)\nlabels = mi_selectlabel(2, 1)\nwrong = fails(mi_drawrectangle, 0, 0, 1)\ncheck(bottom == [0, 0, 4, 0], 'bottom ' + show(bottom))\ncheck(right == [4, 0, 4, 2], 'right ' + show(right))\ncheck(top == [4, 2, 0, 2], 'top ' + show(top))\ncheck(left == [0, 2, 0, 0], 'left ' + show(left))\ncheck(labels == [], 'a block label was added: ' + show(labels))\ncheck(wrong is not None and 'missing 1 required positional argument' in wrong, 'three arguments: ' + str(wrong))\nreturn f'sides of (0,0)-(4,2), start then end: bottom {bottom}; right {right}; top {top}; left {left}; no label; three arguments: {wrong}'")
run('mi_getboundingbox', "blank()\nempty = mi_getboundingbox()\ncheck(empty == [], 'empty document gave ' + show(empty))\nmi_drawarc(10, 0, -10, 0, 180, 1)\nx1, x2, y1, y2 = mi_getboundingbox()\ncheck(near(x1, -10) and near(x2, 10) and abs(y1) < 1e-9 and abs(y2 - 10) < 1e-6, 'half circle: ' + show(x1, x2, y1, y2))\nmi_addblocklabel(0, 30)\nbox = mi_getboundingbox()\ncheck(abs(box[3] - 30) < 1e-9, 'with a label at (0,30): ' + show(box))\nreturn f'empty: {empty}; upper half circle r = 10: {[x1, x2, y1, y2]}; plus a block label at (0,30): {box}'")
run('mi_mirror', "blank()\nmi_drawline(1, 1, 3, 2)\nmi_addblocklabel(5, 2)\nmi_selectsegment(2, 1.5)\nmi_selectlabel(5, 2)\nr = mi_mirror(0, 0, 1, 0)\nmi_deleteselected()\nml, ol = mi_selectlabel(5, -2), mi_selectlabel(5, 2)\nms, osg = mi_selectsegment(2, -1.5), mi_selectsegment(2, 1.5)\nmi_close()\nblank()\nmi_addnode(2, 1)\nmi_addblocklabel(5, 2)\nmi_selectnode(2, 1)\nmi_selectlabel(5, 2)\nmi_mirror(0, 0, 1, 0, 2)\nea_lab, ea_node = mi_selectlabel(5, -2), mi_selectnode(2, -1)\nmi_close()\nblank()\nmi_addpointprop('P', 0, 0)\nmi_addnode(0, 0)\nmi_selectnode(0, 0)\nmi_setnodeprop('P', 5)\nmi_clearselected()\nmi_mirror(0, 0, 1, 0)\nmi_saveas('/tmp/g1_mirror.fem')\nrow = re.search(r'^0\\t0\\t(\\d+)\\t(\\d+)$', open('/tmp/g1_mirror.fem').read(), re.M).groups()\nmi_close()\nblank()\nmi_addmaterial('PM', 1.05, 1.05, 900000, 0, 0, 0, 0, 1, 0, 0, 0, 1, 0)\ncircle(40, 5)\narcprop(0, 40, 5, 'A0')\narcprop(0, -40, 5, 'A0')\nlabel(-20, -20, 'Air')\nmi_drawrectangle(8, -2, 12, 2)\nmi_addblocklabel(10, 0)\nmi_selectlabel(10, 0)\nmi_setblockprop('PM', 1, 0, '<None>', 0, 0, 0)\nmi_clearselected()\nmi_selectrectangle(7, -3, 13, 3, 4)\nmi_mirror(0, 0, 0, 1)\nsolve('geo_mirror')\nb1 = mo_getpointvalues(10, 0)[1:3]\nb2 = mo_getpointvalues(-10, 0)[1:3]\ncheck(ml == [5, -2] and ol == [5, 2], 'labels: mirrored ' + show(ml) + ', original ' + show(ol))\ncheck(ms == [1, -1, 3, -2] and osg == [1, 1, 3, 2], 'segments: mirrored ' + show(ms) + ', original ' + show(osg))\ncheck(ea_lab == [5, -2] and ea_node == [2, 1], 'editaction 2: label ' + show(ea_lab) + ', nearest node to (2,-1) ' + show(ea_node))\ncheck(row == ('0', '0'), 'node (0,0) kept its point property and group: ' + show(row))\ncheck(b1[0] > 0.1 and abs(b1[1]) < 0.15 * b1[0], 'original magnet: B ' + show(b1))\ncheck(b2[0] < -0.1 and abs(b2[1]) < -0.15 * b2[0], 'mirrored magnet at (-10,0): B ' + show(b2))\nreturn f'returned {r}; mirror in the x axis: copies at (5,-2) and {ms}, originals kept, nothing left selected; editaction 2 mirrored the label only; a mirror with nothing selected reset node (0,0) to point property/group {row}; +x magnet mirrored in the y axis: B at (-10,0) = ({b2[0]:.3f}, {b2[1]:.3f}) T, original ({b1[0]:.3f}, {b1[1]:.3f}) T'")
run('mi_moverotate', "blank()\nmi_addblocklabel(5, 0)\nmi_addnode(10, 0)\nmi_selectlabel(5, 0)\nmi_selectnode(10, 0)\nr = mi_moverotate(0, 0, 90)\nmi_moverotate(0, 0, 90)\nlab = mi_selectlabel(5, 0)\nnode = mi_selectnode(10, 0)\nmi_clearselected()\nmi_selectlabel(0, 5)\nmi_selectnode(0, 10)\nmi_moverotate(0, 0, 90, 2)\nlab2 = mi_selectlabel(0, 0)\nnode2 = mi_selectnode(0, 0)\nmi_close()\nblank()\nmi_drawrectangle(8, -1, 12, 1)\nmi_selectrectangle(7, -2, 13, 2, 1)\nmi_setsegmentprop('<None>', 0, 1, 0, 7)\nmi_clearselected()\nmi_addnode(20, 0)\nmi_selectnode(20, 0)\nmi_setnodeprop('<None>', 7)\nmi_clearselected()\nmi_selectgroup(7)\nmi_moverotate(0, 0, 90)\nmi_selectgroup(7)\nmi_moverotate(0, 0, 90)\ncorner = mi_selectnode(-12, 1)\nmi_clearselected()\nbare = mi_selectnode(0, 20)\nmi_seteditmode('nodes')\nmi_close()\nblank()\nmi_addpointprop('P', 0, 0)\nmi_addnode(0, 0)\nmi_selectnode(0, 0)\nmi_setnodeprop('P', 5)\nmi_clearselected()\nmi_moverotate(0, 0, 90)\nmi_saveas('/tmp/g1_moverotate.fem')\nrow = re.search(r'^0\\t0\\t(\\d+)\\t(\\d+)$', open('/tmp/g1_moverotate.fem').read(), re.M).groups()\nmi_close()\nblank()\nmi_addmaterial('PM', 1.05, 1.05, 900000, 0, 0, 0, 0, 1, 0, 0, 0, 1, 0)\ncircle(40, 5)\narcprop(0, 40, 5, 'A0')\narcprop(0, -40, 5, 'A0')\nlabel(-20, -20, 'Air')\nmi_drawrectangle(8, -2, 12, 2)\nmi_addblocklabel(10, 0)\nmi_selectlabel(10, 0)\nmi_setblockprop('PM', 1, 0, '<None>', 0, 0, 0)\nmi_clearselected()\nmi_selectrectangle(7, -3, 13, 3, 4)\nmi_moverotate(0, 0, 90)\nsolve('geo_moverot')\nbx, by = mo_getpointvalues(0, 10)[1:3]\ndef at(p, x, y):\n    return abs(p[0] - x) < 1e-9 and abs(p[1] - y) < 1e-9\ncheck(at(lab, 0, 5), 'label after +90 ' + show(lab))\ncheck(at(node, 0, 10), 'node after +90 ' + show(node))\ncheck(at(lab2, -5, 0), 'label after the editaction 2 turn ' + show(lab2))\ncheck(at(node2, 0, 10), 'the node turned despite editaction 2: ' + show(node2))\ncheck(at(corner, -12, 1), 'corner after two group-7 turns ' + show(corner))\ncheck(at(bare, 0, 20), 'bare group-7 node after two turns ' + show(bare))\ncheck(row == ('0', '0'), 'node (0,0) kept its point property and group: ' + show(row))\ncheck(by > 0.1 and abs(bx) < 0.15 * by, 'magnet turned to (0,10): B ' + show(bx, by))\nreturn f'returned {r}; +90 about (0,0): label (5,0) -> ({lab[0]:.3g}, {lab[1]:.3g}), node (10,0) -> ({node[0]:.3g}, {node[1]:.3g}), and a second turn without reselecting moved nothing; editaction 2 turned the label only; two mi_selectgroup(7) + mi_moverotate(90) steps took a rectangle with group-7 sides to the far side, while a bare group-7 node stopped after the first turn at ({bare[0]:.3g}, {bare[1]:.3g}); a turn with nothing selected reset node (0,0) to point property/group {row}; magnet at (0,10): B = ({bx:.3f}, {by:.3f}) T'")
run('mi_movetranslate', "blank()\nmi_addnode(0, 0)\nmi_addblocklabel(1, 1)\nmi_seteditmode('nodes')\nmi_selectnode(0, 0)\nmi_selectlabel(1, 1)\nr = mi_movetranslate(5, 0)\nmi_movetranslate(5, 0)\nnode, lab = mi_selectnode(0, 0), mi_selectlabel(0, 0)\nmi_close()\nblank()\nmi_addnode(0, 0)\nmi_addblocklabel(1, 1)\nmi_selectnode(0, 0)\nmi_selectlabel(1, 1)\nmi_movetranslate(5, 0, 2)\nnode2, lab2 = mi_selectnode(0, 0), mi_selectlabel(0, 0)\nmi_close()\nblank()\nmi_drawline(0, 0, 0, 2)\nmi_selectsegment(0, 1)\nmi_movetranslate(5, 0, 0)\nseg0 = mi_selectsegment(0, 1)\nmi_clearselected()\nmi_selectsegment(0, 1)\nmi_movetranslate(5, 0, 1)\nseg1 = mi_selectsegment(0, 1)\nmi_close()\n# editaction None on each move and copy command, in arcsegments mode: node (10,0) and\n# label (5,0) are selected, and both must reach the expected place.\nnones = []\nfor op, nd, lb in ((lambda: mi_movetranslate(0, 5, None), (10, 5), (5, 5)),\n                   (lambda: mi_moverotate(0, 0, 90, None), (0, 10), (0, 5)),\n                   (lambda: mi_copytranslate(0, 5, 1, None), (10, 5), (5, 5)),\n                   (lambda: mi_copyrotate(0, 0, 90, 1, None), (0, 10), (0, 5)),\n                   (lambda: mi_scale(0, 0, 2, None), (20, 0), (10, 0)),\n                   (lambda: mi_mirror(0, 0, 0, 1, None), (-10, 0), (-5, 0))):\n    blank()\n    mi_addnode(10, 0)\n    mi_addblocklabel(5, 0)\n    mi_seteditmode('arcsegments')\n    mi_selectnode(10, 0)\n    mi_selectlabel(5, 0)\n    op()\n    got = mi_selectnode(*nd) + mi_selectlabel(*lb)\n    nones.append(len(got) == 4 and all(abs(a - b) < 1e-9 for a, b in zip(got, nd + lb)))\n    mi_seteditmode('nodes')\n    mi_close()\n# Node (0,0) gets point property P and group 5; a segment (with boundary A0), an arc and a\n# label get group 5 too. Then another node is moved, or nothing is selected and moved.\nrows = []\nfor select_other in (True, False):\n    blank()\n    mi_addpointprop('P', 0, 0)\n    mi_addnode(0, 0)\n    mi_addnode(10, 10)\n    mi_drawline(20, 0, 30, 0)\n    mi_drawarc(40, 0, 50, 0, 90, 5)\n    mi_addblocklabel(60, 0)\n    mi_selectnode(0, 0)\n    mi_setnodeprop('P', 5)\n    mi_clearselected()\n    mi_selectsegment(25, 0)\n    mi_setsegmentprop('A0', 0, 1, 0, 5)\n    mi_clearselected()\n    mi_selectarcsegment(45, -3)\n    mi_setarcsegmentprop(5, '<None>', 0, 5)\n    mi_clearselected()\n    mi_selectlabel(60, 0)\n    mi_setblockprop('Air', 1, 0, '<None>', 0, 5, 0)\n    mi_clearselected()\n    mi_saveas('/tmp/g1_move.fem')\n    before = re.search(r'^0\\t0\\t(\\d+)\\t(\\d+)$', open('/tmp/g1_move.fem').read(), re.M).groups()\n    if select_other:\n        mi_selectnode(10, 10)\n    mi_movetranslate(1, 0)\n    mi_saveas('/tmp/g1_move.fem')\n    text = open('/tmp/g1_move.fem').read()\n    after = re.search(r'^0\\t0\\t(\\d+)\\t(\\d+)$', text, re.M).groups()\n    segline = re.search(r'^\\d+\\t\\d+\\t\\S+\\t(\\d+)\\t\\d+\\t(\\d+)$', text, re.M).groups()\n    mi_selectgroup(5)\n    mi_deleteselected()\n    rows.append((before, after, segline, mi_selectnode(0, 0), mi_selectsegment(25, 0), mi_selectarcsegment(45, -3), mi_selectlabel(60, 0)))\n    mi_seteditmode('nodes')\n    mi_close()\ncheck(node == [5, 0] and lab == [6, 1], 'after two moves in nodes mode: node ' + show(node) + ', label ' + show(lab))\ncheck(node2 == [0, 0] and lab2 == [6, 1], 'editaction 2: node ' + show(node2) + ', label ' + show(lab2))\ncheck(seg0 == [0, 0, 0, 2] and seg1 == [5, 0, 5, 2], 'segment after editaction 0: ' + show(seg0) + ', after editaction 1: ' + show(seg1))\ncheck(nones == [True] * 6, 'editaction None (move, rotate, copy, copy-rotate, scale, mirror): ' + show(nones))\nfor before, after, segline, left, seg, arc, lab5 in rows:\n    check(before == ('1', '5'), 'control: node (0,0) was saved with point property/group ' + show(before))\n    check(after == ('0', '0') and left == [0, 0], 'after the move: node saved as ' + show(after) + '; mi_selectgroup(5) then delete left the node at ' + show(left))\n    check(segline == ('1', '5') and seg == [] and arc == [] and lab5 == [], 'segment boundary/group ' + show(segline) + '; left after deleting group 5: ' + show(seg, arc, lab5))\nreturn f'returned {r}; nodes mode, no editaction: node -> {node}, label -> {lab}, and the second move found nothing selected; editaction 2 moved only the label ({lab2}, node {node2}); a selected segment stayed with editaction 0 and moved with its nodes with 1 ({seg1}); editaction None acted on node and label in all six move and copy commands; node (0,0) with point property 1 and group 5 was saved as {rows[0][1]} after moving another node and {rows[1][1]} after a move with nothing selected, while the segment kept boundary/group {rows[1][2]} and the arc and label stayed in group 5'")
run('mi_scale', "blank()\nmi_drawline(2, 2, 4, 2)\nmi_addblocklabel(5, 0)\nmi_selectsegment(3, 2)\nmi_selectlabel(5, 0)\nr = mi_scale(1, 0, 2)\nmi_deleteselected()\nseg = mi_selectsegment(5, 4)\nlab = mi_selectlabel(9, 0)\nmi_close()\nblank()\nmi_addnode(2, 0)\nmi_addblocklabel(3, 3)\nmi_selectnode(2, 0)\nmi_selectlabel(3, 3)\nmi_scale(0, 0, 3, 0)\nnode0, lab0 = mi_selectnode(0, 0), mi_selectlabel(0, 0)\nmi_close()\nblank()\nmi_addpointprop('P', 0, 0)\nmi_addnode(0, 0)\nmi_selectnode(0, 0)\nmi_setnodeprop('P', 5)\nmi_clearselected()\nmi_scale(0, 0, 2)\nmi_saveas('/tmp/g1_scale.fem')\nrow = re.search(r'^0\\t0\\t(\\d+)\\t(\\d+)$', open('/tmp/g1_scale.fem').read(), re.M).groups()\ncheck(seg == [3, 4, 7, 4], 'segment (deleted while still selected?) ' + show(seg))\ncheck(lab == [9, 0], 'label ' + show(lab))\ncheck(node0 == [6, 0] and lab0 == [3, 3], 'editaction 0: node ' + show(node0) + ', label ' + show(lab0))\ncheck(row == ('0', '0'), 'node (0,0) kept its point property and group: ' + show(row))\nreturn f'returned {r}; x2 about (1,0): segment (2,2)-(4,2) -> {seg}, label (5,0) -> {lab}, nothing left selected; editaction 0, x3: node (2,0) -> {node0}, label stayed at {lab0}; a scale with nothing selected reset node (0,0) to point property/group {row}'")
run('mi_selectarcsegment', "blank()\nnone = mi_selectarcsegment(0, 0)\ncircle(10, 5)\narc = mi_selectarcsegment(1, -12)\nmi_selectarcsegment(1, -12)\nmi_deleteselectedarcsegments()\nagain = mi_selectarcsegment(1, -12)\ncheck(none == [], 'no arcs, yet it returned ' + show(none))\ncheck(arc == [-10, 0, 10, 0], 'lower arc ' + show(arc))\ncheck(again == arc, 'the arc was deleted after being selected twice: ' + show(again))\nreturn f'empty model -> {none}; lower half of circle(10) -> {arc}; a second call deselected it'")
run('mi_selectcircle', "blank()\nmi_drawrectangle(0, 0, 10, 10)\nmi_addblocklabel(5, 5)\nr = mi_selectcircle(0, 0, 10.5, 1)\nmi_deleteselectedsegments()\nseg = mi_selectsegment(2, 1)\nmi_clearselected()\nnode = mi_selectnode(0, 0)\nmi_clearselected()\nmi_selectcircle(5, 5, 1, 2)\nmi_selectcircle(5, 5, 1, 2)\nmi_deleteselectedlabels()\nlab = mi_selectlabel(5, 5)\nmi_addblocklabel(5, 5)\nmi_seteditmode('blocks')\nmi_selectcircle(5, 5, 20, None)\nmi_deleteselected()\nlab2 = mi_selectlabel(5, 5)\nmi_clearselected()\nnode2 = mi_selectnode(10, 10)\nmi_clearselected()\nraw = callfemm('mi_selectcircle(5, 5, 1, 0)')\nmi_seteditmode('nodes')\nmi_close()\nblank()\n# arc (20,0) -> (20,10), 180 degrees: centre (20,5), it bulges out to x = 25\nmi_drawarc(20, 0, 20, 10, 180, 5)\nmi_selectcircle(20, 0, 9, 3)\nmi_deleteselectedarcsegments()\none_end = mi_selectarcsegment(25, 5)\nmi_clearselected()\nmi_selectcircle(18, 5, 5.5, 3)\nmi_deleteselectedarcsegments()\nboth_ends = mi_selectarcsegment(25, 5)\ncheck(one_end == [20, 0, 20, 10] and both_ends == [], 'arc with one end inside: ' + show(one_end) + '; with both ends inside but its bulge out: ' + show(both_ends))\ncheck(seg == [10, 0, 10, 10], 'nearest remaining segment to (2,1) ' + show(seg))\ncheck(node == [0, 0], 'node (0,0) went: ' + show(node))\ncheck(lab == [], 'editmode 2 twice did not leave the label selected')\ncheck(lab2 == [] and node2 == [10, 10], 'editmode None in blocks mode: label ' + show(lab2) + ', nearest node ' + show(node2))\ncheck(r is None and raw == [], 'returned ' + show(r, raw))\nreturn f'returned {r} (FEMM replied {raw}); R = 10.5 about (0,0) with editmode 1 took only the left and bottom sides (both ends inside), no nodes; editmode 2 given twice still selected the label; editmode None used the current (blocks) mode; an arc was taken only with both ends inside, even with its bulge outside'")
run('mi_selectgroup', "fixture_pre()\nmi_seteditmode('nodes')\nmi_selectlabel(5, 0)\nr = mi_selectgroup(2)\nmi_selectgroup(2)\nmi_deleteselectedlabels()\nbefore = mi_selectlabel(5, 0)\niron = mi_selectlabel(25, 0)\nmi_clearselected()\nmi_selectcircle(30, 0, 1)\nmi_deleteselectedlabels()\nouter = mi_selectlabel(30, 0)\nmi_clearselected()\nraw = callfemm('mi_selectgroup(1)')\nmi_seteditmode('nodes')\nmi_close()\nblank()\nmi_drawrectangle(8, -1, 12, 1)\nmi_selectrectangle(7, -2, 13, 2, 1)\nmi_setsegmentprop('<None>', 0, 1, 0, 7)\nmi_clearselected()\nmi_addnode(20, 0)\nmi_selectnode(20, 0)\nmi_setnodeprop('<None>', 7)\nmi_clearselected()\nmi_selectgroup(7)\nmi_moverotate(0, 0, 90)\nmi_selectgroup(7)\nmi_moverotate(0, 0, 90)\ncorner = mi_selectnode(-12, 1)\nmi_clearselected()\nbare = mi_selectnode(0, 20)\nmi_seteditmode('nodes')\ncheck(iron == [30, 0], 'the group 2 label (25,0) was not deleted: nearest ' + show(iron))\ncheck(before == [0, 0], 'the label selected before mi_selectgroup survived: nearest to (5,0) ' + show(before))\ncheck(outer != [30, 0], 'mi_selectcircle without editmode did not take the label at (30,0): mode is not group')\ncheck(r is None and raw == [], 'returned ' + show(r, raw))\ncheck(abs(corner[0] + 12) < 1e-9 and abs(corner[1] - 1) < 1e-9, 'outline corner after two group-7 turns ' + show(corner))\ncheck(abs(bare[0]) < 1e-9 and abs(bare[1] - 20) < 1e-9, 'bare group-7 node after two turns ' + show(bare))\nreturn f'returned {r} (FEMM replied {raw}); label (5,0), selected beforehand, was deleted with group 2 (selected twice); then mi_selectcircle without editmode took a label (group mode); two mi_selectgroup(7) + mi_moverotate(90) steps: outline corner at {corner}, the bare group-7 node stopped after the first turn at {bare}'")
run('mi_selectlabel', "blank()\nnone = mi_selectlabel(0, 0)\nmi_addblocklabel(3, 4)\nmi_addblocklabel(-7, 1)\nfirst = mi_selectlabel(0, 0)\nmi_selectlabel(0, 0)\nmi_deleteselectedlabels()\nagain = mi_selectlabel(0, 0)\ncheck(none == [], 'no labels, yet it returned ' + show(none))\ncheck(first == [3, 4], 'returned ' + show(first))\ncheck(again == [3, 4], 'the label was deleted after being selected twice: ' + show(again))\nreturn f'empty model -> {none}; (0,0) selected the label at {first}; a second call deselected it'")
print("BATCH_DONE", flush=True)
closefemm()
